#!/usr/bin/env node
/**
 * generate-filesystem-mirrors.mjs — part of core's build: writes
 * src/runtime/filesystem-mirrors.generated.ts from the filesystem method
 * table (src/runtime/filesystem-methods.ts FILESYSTEM_METHODS).
 *
 * The table names each bridge method's RPC name and how its answer crosses a
 * hop; the generated file spells both mirrors out, one arrow per method, so
 * the compiler checks every method's arguments and answer on both sides
 * against RuntimeFsBridge, where a mirror built by reflection would erase
 * them. tests/unit/filesystem-mirrors.mjs regenerates the text from the
 * source table and compares it with the committed file.
 */

import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const coreRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const runtimeDir = join(coreRoot, 'src', 'runtime');
export const FILESYSTEM_MIRRORS_GENERATED = join(runtimeDir, 'filesystem-mirrors.generated.ts');

/** The answer kinds the table may name, and the transport each is repaired by. */
const TRANSPORT = { value: 'answerValue', bytes: 'answerBytes', stream: 'answerStream' };

/** The generated file's text for `methods` (FILESYSTEM_METHODS). */
export function filesystemMirrorsSource(methods) {
  const entries = Object.entries(methods);
  for (const [method, { rpc, answer }] of entries) {
    if (!/^[A-Za-z_$][\w$]*$/.test(method) || !/^[A-Za-z_$][\w$]*$/.test(rpc)) {
      throw new Error(`filesystem method ${method} → ${rpc}: not identifiers`);
    }
    if (!Object.hasOwn(TRANSPORT, answer)) throw new Error(`filesystem method ${method}: unknown answer kind ${answer}`);
  }
  const answered = entries.filter(([, { answer }]) => answer !== 'stream');
  return [
    '/**',
    ' * filesystem-mirrors.generated.ts — AUTO-GENERATED by',
    ' * packages/core/scripts/generate-filesystem-mirrors.mjs from',
    ' * filesystem-methods.ts FILESYSTEM_METHODS. Do not edit: edit the table and',
    " * run core's build.",
    ' */',
    '',
    "import type { RuntimeFsBridge } from './os-contracts.js';",
    "import { answerBytes, answerStream, answerValue, type FILESYSTEM_METHODS, type FilesystemSupervisor } from './filesystem-methods.js';",
    '',
    '/** Bridge method → its name on the supervisor RPC capability. */',
    'export const FILESYSTEM_RPC_METHODS = {',
    ...entries.map(([method, { rpc }]) => `  ${method}: '${rpc}',`),
    "} as const satisfies { readonly [K in keyof typeof FILESYSTEM_METHODS]: typeof FILESYSTEM_METHODS[K]['rpc'] };",
    '',
    '/** The RPC names a facet calls through `answer`: every method but a streamed one. */',
    'export const FILESYSTEM_ANSWERED_RPC_METHODS = [',
    ...answered.map(([, { rpc }]) => `  '${rpc}',`),
    '] as const satisfies readonly (keyof FilesystemSupervisor)[];',
    '',
    '/** Local facets retain the process-bound bridge and its synchronous capability. */',
    'export function vfsSupervisor(fs: RuntimeFsBridge): FilesystemSupervisor {',
    '  return {',
    '    synchronous: fs.synchronous,',
    ...entries.map(([method, { rpc }]) => `    ${rpc}: (...args) => fs.${method}(...args),`),
    '  };',
    '}',
    '',
    '/**',
    ' * The bridge over `supervisor`, each answer repaired for the hop it crossed',
    " * by its kind; the capabilities that stay in their isolate are `local`'s.",
    ' */',
    'export function bridgeOverSupervisor(',
    '  supervisor: FilesystemSupervisor,',
    "  local: Pick<RuntimeFsBridge, 'synchronous' | 'writeFileFrom'>,",
    '): RuntimeFsBridge {',
    '  return {',
    '    synchronous: local.synchronous,',
    '    writeFileFrom: local.writeFileFrom,',
    ...entries.map(([method, { rpc, answer }]) => `    ${method}: (...args) => ${TRANSPORT[answer]}(supervisor.${rpc}(...args)),`),
    '  };',
    '}',
    '',
  ].join('\n');
}

/** FILESYSTEM_METHODS, read by bundling the table module (it imports only types). */
async function loadMethods() {
  const result = await build({
    entryPoints: [join(runtimeDir, 'filesystem-methods.ts')],
    bundle: true,
    format: 'esm',
    platform: 'neutral',
    write: false,
    logLevel: 'silent',
  });
  const code = result.outputFiles[0].text;
  const module = await import(`data:text/javascript;base64,${Buffer.from(code).toString('base64')}`);
  return module.FILESYSTEM_METHODS;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(FILESYSTEM_MIRRORS_GENERATED, filesystemMirrorsSource(await loadMethods()));
}
